package com.mathengine.storage;import android.content.Context;import java.util.ArrayList;import java.util.List;
public final class HistoryStore{private static final String PREF="calculator_history";private final android.content.SharedPreferences prefs;public HistoryStore(Context c){prefs=c.getSharedPreferences(PREF,Context.MODE_PRIVATE);}public void add(String e,String r){String old=prefs.getString("items","");String next=e+"\t"+r+(old.isEmpty()?"":"\n"+old);String[] rows=next.split("\n");StringBuilder b=new StringBuilder();for(int i=0;i<Math.min(rows.length,100);i++){if(i>0)b.append('\n');b.append(rows[i]);}prefs.edit().putString("items",b.toString()).apply();}public List<String> all(){String raw=prefs.getString("items","");List<String> out=new ArrayList<>();if(!raw.isEmpty())java.util.Collections.addAll(out,raw.split("\n"));return out;}public void clear(){prefs.edit().remove("items").apply();}}
